{"code_completion": "module TopModule (
    input  clk,
    input  reset,
    input  in,
    output out
);

    // state: 1'b1 = B (out=1), 1'b0 = A (out=0)
    reg state;

    always @(posedge clk) begin
        if (reset) begin
            state <= 1'b1; // reset to state B
        end else begin
            if (!in) begin
                state <= ~state; // toggle on in=0
            end
            // if in=1, hold current state
        end
    end

    assign out = state;

endmodule"}
